from lib import *
S = SS('x110')
steps = [
    step("签名与基本校验(用 JwtValidators.createDefault(),只校验时间)。不带令牌 GET /read:401,WWW-Authenticate: Bearer resource_metadata=…。有效令牌(scope = read write、roles = [ADMIN]):/read 200,authorities 是 [SCOPE_read, SCOPE_write, FACTOR_BEARER]——scope 被映射成 SCOPE_ 开头的权限,Spring Security 7 还加了一条 FACTOR_BEARER;同一个令牌访问需要 hasRole(\"ADMIN\") 的 /admin 是 403(error=insufficient_scope),因为令牌里的 roles 声明默认不会被当成角色;没有 scope 的令牌访问 /read 也是 403。恶意令牌都是 401 且 error=invalid_token:篡改了 payload → Signed JWT rejected: Invalid signature;alg = none → Unsupported algorithm of none;alg = HS256 并拿公钥字节当密钥 → Signed JWT rejected: Another algorithm expected, or no matching key(s) found;过期 90 秒 → Jwt expired at …;nbf 在 120 秒之后 → Jwt used before …。一个危险的默认:iss 是别的签发者(https://evil.example)的令牌,在默认的 createDefault() 下是 200 通过——默认只校验时间,不校验签发者。", t=tl(S(1)), mark=lidx(S(1), 'GET /admin', 'iss 是别的签发者的令牌'), done=lidx(S(1), '有效令牌 GET /read', '篡改了', 'alg = none', 'HS256', '过期 90 秒', 'nbf'), b=bars([['有效令牌访问 /read', 200, '200'], ['有效令牌访问 /admin(roles = [ADMIN])', 403, '403'], ['篡改后的令牌', 401, '401'], ['iss 是别的签发者的令牌(默认校验)', 200, '200(未被拒绝)']], 403, mark=[1, 3], done=[0, 2]), kv=KV([['scope 声明', '映射成 SCOPE_xxx 权限'], ['roles 声明', '默认不会变成角色,hasRole 通不过'], ['签名与算法', '篡改、none、HS256 混淆都被拒绝'], ['默认校验', '只校验时间,不校验 iss']], ['默认校验'])),
    step("时钟偏差与签发者。默认的时间校验容忍 60 秒偏差:过期 30 秒的令牌 → 200;过期 90 秒 → 401(Jwt expired at …)。换成 JwtTimestampValidator(Duration.ZERO):过期 30 秒的令牌 → 401。要校验签发者要显式用 JwtValidators.createDefaultWithIssuer(\"https://issuer.example\"):iss 不对的令牌 → 401(The iss claim is not valid),iss 正确的 → 200。", t=tl(S(2)), mark=lidx(S(2), 'Duration.ZERO', 'createDefaultWithIssuer'), done=lidx(S(2), '过期 30 秒的令牌(默认)', '过期 90 秒的令牌(默认)'), b=bars([['过期 30 秒的令牌(默认容忍 60 秒)', 200, '200'], ['过期 90 秒的令牌(默认)', 401, '401'], ['过期 30 秒的令牌(Duration.ZERO)', 401, '401'], ['iss 不对的令牌(createDefaultWithIssuer)', 401, '401']], 401, done=[0], mark=[1, 2, 3]), kv=KV([['默认容忍', '60 秒时钟偏差'], ['Duration.ZERO', '不容忍,过期 30 秒就拒绝'], ['签发者', '用 createDefaultWithIssuer 才会校验'], ['错误信息', 'Jwt expired at … / The iss claim is not valid']], ['默认容忍'])),
    step("JWKS 与密钥轮换(JWKS 服务从 {k1} 切到 {k2})。第 1 步 JWKS = {k1}:k1 令牌 200,JWKS 服务被访问 1 次。第 2 步把 JWKS 切成 {k2},立刻拿 k2 签名的令牌:200——kid 不在缓存里时会重新去取 JWKS(服务又被访问 1 次)。第 3 步再用 k1 令牌:401(Signed JWT rejected: Another algorithm expected, or no matching key(s) found)——刚才为 k2 令牌触发的刷新已经把缓存换成了 {k2},k1 立刻失效,没有「旧密钥继续有效一段时间」的宽限期。等 16 秒之后 k2 令牌仍是 200,k1 令牌还是 401,累计 JWKS 服务被访问 4 次(从这个数字看,缓存里没有的 kid 会让它再去取,我没有测它有没有限流)。第 6 步把 JWKS 服务停掉:已缓存的 k2 令牌仍是 200;但如果在 JWKS 服务宕机时才启动应用,k2 令牌 401。所以轮换密钥时 JWKS 里要同时发布新旧两把,等旧令牌都过期之后再撤旧的。", t=tl(S(3)), mark=lidx(S(3), '第 3 步', '第 5 步', '刚启动的应用'), done=lidx(S(3), '第 1 步', '第 2 步', '第 4 步', '第 6 步'), b=bars([['JWKS 切成 {k2} 之后立刻:k2 令牌', 200, '200'], ['同时:k1 令牌', 401, '401'], ['JWKS 宕机:已缓存的 k2 令牌', 200, '200'], ['JWKS 宕机时才启动的应用:k2 令牌', 401, '401']], 401, mark=[1, 3], done=[0, 2]), kv=KV([['kid 不在缓存里', '重新去取 JWKS,新令牌立刻可用'], ['旧 key', '缓存被换成新 JWKS 后立即失效,没有宽限期'], ['JWKS 宕机', '已缓存的 key 继续可用;刚启动的应用验证不了'], ['轮换做法', 'JWKS 同时发布新旧两把,旧令牌过期后再撤']], ['旧 key'])),
    step("scope 与 roles 怎么变成 authorities。令牌 scope = \"read write\" 访问 /read:200,authorities 是 [FACTOR_BEARER, SCOPE_read, SCOPE_write];访问任意其他路径同样如此。令牌里的 roles = [ADMIN] 没有变成 ROLE_ADMIN(上面 /admin 是 403)。想用 roles 声明做 hasRole,要自己写 JwtAuthenticationConverter,把 roles 映射成 ROLE_ 开头的权限;或者直接在 hasAuthority 里使用 SCOPE_ 权限。", t=tl(S(4)), mark=lidx(S(4), 'GET /read', 'GET /anything'), done=[], b=bars([['scope 映射成的 SCOPE_ 权限个数', 2, '2'], ['roles 映射成的 ROLE_ 权限个数', 0, '0']], 2, mark=[0], done=[1]), kv=KV([['scope', '→ SCOPE_read、SCOPE_write'], ['roles 声明', '默认被忽略'], ['要用 hasRole', '自定义 JwtAuthenticationConverter'], ['Spring Security 7', 'authorities 里还多一条 FACTOR_BEARER']], ['roles 声明'])),
]
A = mkartx('x110', 110, 'Spring,Security,JWT,资源服务器,JWKS,密钥轮换,真实验证,动画演示',
    '实测 Spring Security 7 的 JWT 资源服务器:scope 映射成 SCOPE_ 权限、roles 声明默认被忽略;篡改、alg=none、HS256 混淆的令牌都被拒绝;默认的校验只看时间不看签发者,别的 iss 的令牌也会通过;时间偏差默认容忍 60 秒;JWKS 里 kid 不在缓存时会立即重新获取,切换到新密钥后旧密钥立即失效;JWKS 服务宕机时已缓存的密钥继续可用。',
    'JWT 资源服务器默认校验了什么、没校验什么?roles 声明为什么 hasRole 不认?时钟偏差有多大容忍?密钥轮换的时候旧令牌会怎么样?这篇在 Spring Boot 4.0.8、Spring Security 7 上自己签令牌、自己起 JWKS 服务逐项实测。',
    [('iss 不对也通过', '默认的 JwtValidators.createDefault() 只校验时间,别的签发者的令牌返回 200'), ('60 秒', '默认时钟偏差容忍:过期 30 秒通过,过期 90 秒 401'), ('旧 key 立即失效', 'JWKS 换成新 key 之后,k1 令牌马上 401,没有宽限期')],
    [('默认校验', '<p>签名与算法被严格检查;时间有 60 秒容忍;签发者默认不校验;scope 映射成 SCOPE_,roles 被忽略。</p>'),
     ('时钟与签发者', '<p>JwtTimestampValidator 可调容忍;createDefaultWithIssuer 校验 iss。</p>'),
     ('JWKS 轮换', '<p>kid 不在缓存时立即重新获取;旧 key 立刻失效;JWKS 宕机时已缓存的 key 可用。</p>'),
     ('authorities', '<p>scope 映射成 SCOPE_xxx;roles 要自己写转换器。</p>')],
    steps,
    [ENV_X + '(Spring Security 7.0.7、Nimbus JOSE JWT 10.4)。RS256 令牌由我自己用 Nimbus 生成(两把密钥 k1、k2);JWKS 由一个本地 Python http.server 提供,可切换文件和模拟宕机;JwtDecoder 是 NimbusJwtDecoder.withJwkSetUri 构造的,校验器通过 -Dx110.mode 切换;JWKS 的缓存时长我没有读配置,只通过上述步骤观察行为',
     '没有验证:JWKS 缓存的 TTL 具体是多少、重新获取的限流(这里只看到了 16 秒后的结果);issuer-uri 自动发现;不透明令牌(introspection);aud 受众校验;多个签发者(JwtIssuerAuthenticationManagerResolver);令牌撤销与黑名单;DPoP 与 mTLS 绑定令牌;密钥轮换的服务端(授权服务器)如何发布新旧两把 key'],
    'JWT 资源服务器')
